  $path=[IO.Path]::GetFullPath((Join-Path $RepoRoot $Relative));$prefix=$RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
  Assert-A04 $path.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase) "[mir4-a04-path-escape] $Relative"
  if($Required){Assert-A04 (Test-Path -LiteralPath $path -PathType Leaf) "[mir4-a04-missing] $Relative"};return $path
}
function Resolve-A04Directory { param([string]$Relative,[bool]$Required=$true)
  Assert-A04 ($Relative -cmatch '^[A-Za-z0-9._/-]+$' -and $Relative -notmatch '(^|/)\.\.(/|$)') "[mir4-a04-relative-directory] $Relative"
  $path=[IO.Path]::GetFullPath((Join-Path $RepoRoot $Relative));$prefix=$RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
  Assert-A04 $path.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase) "[mir4-a04-directory-escape] $Relative"
  if($Required){Assert-A04 (Test-Path -LiteralPath $path -PathType Container) "[mir4-a04-directory-missing] $Relative"};return $path
}
function Get-A04Relative { param([string]$Path)
  $full=[IO.Path]::GetFullPath($Path);$prefix=$RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
  Assert-A04 $full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase) '[mir4-a04-private-path]'
  return $full.Substring($prefix.Length).Replace('\','/')
}
function Get-A04Artifact { param([string]$Relative)
  $path=Resolve-A04Path $Relative $true;$identity=Get-MIR4RawFileIdentity -Path $path
  return [pscustomobject][ordered]@{path=$Relative;bytes=[long]$identity.bytes;raw_sha256=[string]$identity.sha256}
